  function _originPrefix() {
    try { return location.origin.replace(/[^a-zA-Z0-9]/g, "_"); } catch { return "unknown"; }
  }
  function _scopePath(path) {
    if (!_isMODEFS()) return path;
    var prefix = "/" + _originPrefix();
    var norm = "/" + path.replace(/^\/+|\/+$/g, "");
    return norm.startsWith(prefix + "/") || norm === prefix ? norm : prefix + norm;
  }
  function _unscopePath(path) {
    if (!_isMODEFS()) return path;
    var prefix = "/" + _originPrefix();
    return path.startsWith(prefix) ? path.slice(prefix.length) || "/" : path;
  }
