      "! \" # $ % & ' ( ) * + , - . / : ; < = > ? @ [ \\ ] ^ _ ` { | } ~".split(" ").forEach(t => v.add(t));
      ["...", "..", "!!", "??", "?!", ":-)", ":-(", ":)", ":(", "-->", "=>", "->", "!=", "==", "===", "!==",
       ">=", "<=", "&&", "||", "++", "--", "**", "//", "/*", "*/", "#{", "${", "`", "```"].forEach(t => v.add(t));

