        // additional common
        "able","absolutely","actually","add","added","against","age","ages","agree","ahead","allow",
        "allowed","allows","almost","along","already","although","always","answer","answers","appear",
        "appears","apply","approach","around","asked","aspect","aspects","available","based","basic",
        "become","begin","begins","believe","below","between","bring","build","built","call","called",
