        "SharedWorker","MessageChannel","MessagePort","postMessage","addEventListener",
        "removeEventListener","dispatchEvent","CustomEvent","Event","AbortController","signal",
        "IndexedDB","IDBKeyRange","IDBObjectStore","OPFS","getDirectory","getFileHandle","open",
        "read","write","truncate","close","seek","flush","persist","estimate","grant","query",
        "html","css","js","jsx","ts","tsx","json","xml","yaml","toml","md","markdown","svg","png",
        "jpg","jpeg","gif","webp","mp4","mp3","wav","wasm","wat","wasm32","wasm64",
        "http","https","ws","wss","ftp","ssh","tcp","udp","quic","h3","http3","tls","ssl",
        "get","post","put","delete","patch","options","head","connect","trace",
        "200","201","204","301","302","400","401","403","404","405","500","502","503",
