      if (!img.complete || !img.naturalWidth) return;
      const name = `${prefix}-${i}`;
      const rect = img.getBoundingClientRect();
      const x = opts.x ?? Math.round(rect.left * (SPD_WIDTH  / window.innerWidth));
      const y = opts.y ?? Math.round(rect.top  * (SPD_HEIGHT / window.innerHeight));
      const w = opts.width  ?? Math.round(rect.width  * (SPD_WIDTH  / window.innerWidth));
