    const iv   = crypto.getRandomValues(new Uint8Array(12));
    const data = await crypto.subtle.encrypt({name:'AES-GCM', iv}, key, enc.encode(html));
    const out  = new Uint8Array(12 + data.byteLength);
    out.set(iv, 0);
    out.set(new Uint8Array(data), 12);
