          try { pc.close(); } catch(e) {}
          const arr = [...ips];
          const priv = /^(10\.|172\.(1[6-9]|2\d|3[01])\.|192\.168\.|127\.|169\.254\.)/;
          resolve({ supported: true, ips: arr, hasServerIP: arr.some(ip => !priv.test(ip)) });
