  async function spAuthVerify() {
    try {
      if (!window.sp) return { verified: false, reason: 'SP not loaded' };
      const challenge = crypto.getRandomValues(new Uint8Array(32));
      const challengeHex = Array.from(challenge).map(b => b.toString(16).padStart(2,'0')).join('');
      const identity = await window.sp.identity();
      if (!identity) return { verified: false, reason: 'no SP identity' };
      const sig = await identity.sign(challengeHex);
      const valid = await identity.verify(challengeHex, sig);
      return { verified: valid, spAddr: identity.addr, reason: valid ? null : 'challenge-response failed' };
    } catch(e) {
      return { verified: false, reason: e.message };
    }
  }

