  async function injectPayload(secret) {
    const el = document.getElementById('wg-payload');
    if (!el) return;
    const b64 = el.textContent.trim();
    if (!b64 || b64 === 'DEMO_UNENCRYPTED') return;
    if (!window.WGEncrypt) return;
    try {
      const html   = await window.WGEncrypt.decrypt(b64, secret);
      const parser = new DOMParser();
      const doc    = parser.parseFromString(html, 'text/html');
      doc.head.querySelectorAll('link,style,meta').forEach(n =>
        document.head.appendChild(document.importNode(n, true))
      );
      document.body.innerHTML = doc.body.innerHTML;
      document.body.querySelectorAll('script').forEach(old => {
        const s = document.createElement('script');
        if (old.src) s.src = old.src; else s.textContent = old.textContent;
        old.replaceWith(s);
      });
      el.remove();
    } catch(e) {}
  }

