    const noTZ = tzOffset === 0;
    const missingAPIs = [!('bluetooth' in navigator), !('usb' in navigator), !('hid' in navigator), !('serial' in navigator)].filter(Boolean).length;
    if (isDesktopUA && missingAPIs >= 4 && noTZ && cores <= 2) return true;
