  function detectConnection() {
    const conn = navigator.connection || navigator.mozConnection || navigator.webkitConnection;
    if (!conn) return 'unknown';
    const type = (conn.type || conn.effectiveType || '').toLowerCase();
    if (type === 'wifi' || type === 'ethernet') return type;
    if (type === 'cellular' || /2g|3g|4g|5g/.test(type)) return 'cellular';
    if (type === 'none') return 'none';
    const et = (conn.effectiveType || '').toLowerCase();
    if (et === '4g') return 'wifi';
    if (et === '3g' || et === '2g' || et === 'slow-2g') return 'cellular';
    return 'unknown';
  }

  let honeypotTriggered = false;
